import React, { useState, useEffect } from "react";
import {
  collection,
  addDoc,
  getDocs,
  deleteDoc,
  doc,
  updateDoc,
} from "firebase/firestore";
import { createUserWithEmailAndPassword, deleteUser } from "firebase/auth";
import { db, auth } from "../../firebaseConfig"; // Ensure firebaseConfig includes both db and auth setup
import "./ManageTeachers.css";

const AdminManageTeachers = () => {
  const [teachers, setTeachers] = useState([]);
  const [form, setForm] = useState({
    name: "",
    username: "",
    password: "",
    subject: "",
  });
  const [editId, setEditId] = useState(null);

  const teachersCollectionRef = collection(db, "teachers");

  // Fetch teachers from Firestore
  const fetchTeachers = async () => {
    const data = await getDocs(teachersCollectionRef);
    setTeachers(data.docs.map((doc) => ({ ...doc.data(), id: doc.id })));
  };

  useEffect(() => {
    fetchTeachers();
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setForm({ ...form, [name]: value });
  };

  const addOrUpdateTeacher = async (e) => {
    e.preventDefault();

    if (editId) {
      // Update teacher in Firestore
      const teacherDoc = doc(db, "teachers", editId);
      await updateDoc(teacherDoc, form);
      fetchTeachers();
      setEditId(null);
    } else {
      try {
        // Create user in Firebase Authentication
        const userCredential = await createUserWithEmailAndPassword(
          auth,
          form.username + "@example.com", // Using username as email for Firebase Authentication
          form.password
        );
        const userId = userCredential.user.uid;

        // Add teacher details to Firestore
        await addDoc(teachersCollectionRef, { ...form, authId: userId });
      } catch (error) {
        console.error("Error creating teacher:", error.message);
        alert("Error creating teacher. Please try again.");
        return;
      }
    }

    setForm({ name: "", username: "", password: "", subject: "" });
    fetchTeachers();
  };

  const deleteTeacher = async (id, authId) => {
    try {
      // Delete teacher from Firestore
      const teacherDoc = doc(db, "teachers", id);
      await deleteDoc(teacherDoc);

      // Delete user from Firebase Authentication
      const user = await auth.getUser(authId); // Ensure authId is stored in Firestore
      if (user) {
        await deleteUser(user);
      }
    } catch (error) {
      console.error("Error deleting teacher:", error.message);
    }

    fetchTeachers();
  };

  const editTeacher = (teacher) => {
    setForm(teacher);
    setEditId(teacher.id);
  };

  return (
    <div className="manage-teachers-container">
      <h2>Manage Teachers</h2>
      <form onSubmit={addOrUpdateTeacher} className="teacher-form">
        <label htmlFor="name">Name:</label>
        <input
          type="text"
          id="name"
          name="name"
          value={form.name}
          onChange={handleInputChange}
          required
        />

        <label htmlFor="username">Username:</label>
        <input
          type="text"
          id="username"
          name="username"
          value={form.username}
          onChange={handleInputChange}
          required
        />

        <label htmlFor="password">Password:</label>
        <input
          type="password"
          id="password"
          name="password"
          value={form.password}
          onChange={handleInputChange}
          required
        />

        <label htmlFor="subject">Subject:</label>
        <input
          type="text"
          id="subject"
          name="subject"
          value={form.subject}
          onChange={handleInputChange}
          required
        />

        <button type="submit" className="form-btn">
          {editId ? "Update Teacher" : "Add Teacher"}
        </button>
      </form>

      <div className="teacher-list">
        <h3>Teacher List</h3>
        {teachers.map((teacher) => (
          <div key={teacher.id} className="teacher-item">
            <p>{teacher.name} - {teacher.subject}</p>
            <button onClick={() => editTeacher(teacher)}>Edit</button>
            <button onClick={() => deleteTeacher(teacher.id, teacher.authId)}>Delete</button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AdminManageTeachers;
